from pathlib import Path
import base64
from PIL import Image
import io
OUT=Path('public/brand/materials')
logo=base64.b64encode(Path('public/brand/logo-primary.svg').read_bytes()).decode()
buf=io.BytesIO();Image.open('public/media/app-ui-poster.webp').save(buf,format='PNG');ui=base64.b64encode(buf.getvalue()).decode()
def svg(w,h,content):return f'''<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}"><defs><linearGradient id="g"><stop stop-color="#d5f4e7"/><stop offset=".55" stop-color="#dde8f6"/><stop offset="1" stop-color="#d6caf5"/></linearGradient><clipPath id="phone"><rect x="0" y="0" width="280" height="606" rx="26"/></clipPath></defs><rect width="100%" height="100%" fill="#f7faf8"/><ellipse cx="{w*.8}" cy="{h*.55}" rx="{w*.6}" ry="{h*.65}" fill="url(#g)"/>{content}</svg>'''
banner=f'''<image x="90" y="70" width="275" height="85" href="data:image/svg+xml;base64,{logo}"/><text x="90" y="235" font-family="Arial,sans-serif" font-size="17" letter-spacing="3" fill="#007d78">MORTGAGE BROKER IN DUBAI &amp; UAE</text><g font-family="Arial,sans-serif" font-size="91" font-weight="600" letter-spacing="-4"><text x="85" y="365" fill="#081d37">Mortgages, with</text><text x="85" y="467" fill="#007d78">more perspective.</text></g><text x="90" y="548" font-family="Arial,sans-serif" font-size="25" fill="#536b73">Clear options. Real costs. Your next home.</text><rect x="90" y="608" width="290" height="66" rx="33" fill="#081d37"/><text x="124" y="650" font-family="Arial,sans-serif" font-size="21" fill="#fff">Plan a better way</text><text x="90" y="798" font-family="Arial,sans-serif" font-size="16" fill="#607a75">Betterway Mortgages · hello@betterwaymortgages.com</text><g transform="translate(1130 134) rotate(8)"><rect x="-8" y="-8" width="296" height="622" rx="36" fill="#152a36" stroke="#a8b8c1" stroke-width="4"/><image width="280" height="606" href="data:image/png;base64,{ui}" clip-path="url(#phone)"/></g><rect x="1010" y="610" width="260" height="97" rx="19" fill="white"/><text x="1035" y="649" font-family="Arial,sans-serif" font-size="15" fill="#007d78">YOUR HOME. YOUR NUMBERS.</text><text x="1035" y="679" font-family="Arial,sans-serif" font-size="19" fill="#081d37">Planning made clearer.</text><text x="1025" y="796" font-family="Arial,sans-serif" font-size="13" fill="#708782">Illustrative product interface · Not a bank offer</text>'''
flyer=f'''<image x="65" y="60" width="260" height="80" href="data:image/svg+xml;base64,{logo}"/><text x="65" y="219" font-family="Arial,sans-serif" font-size="15" letter-spacing="2" fill="#007d78">YOUR NEXT MOVE STARTS WITH CLARITY.</text><g font-family="Arial,sans-serif" font-size="75" font-weight="600" letter-spacing="-3"><text x="60" y="316" fill="#081d37">Know your costs.</text><text x="60" y="399" fill="#007d78">Find your way home.</text></g><text x="65" y="459" font-family="Arial,sans-serif" font-size="22" fill="#536b73">Mortgage planning for Dubai &amp; the UAE.</text><g transform="translate(490 515) rotate(7)"><rect x="-8" y="-8" width="296" height="622" rx="36" fill="#152a36" stroke="#a8b8c1" stroke-width="4"/><image width="280" height="606" href="data:image/png;base64,{ui}" clip-path="url(#phone)"/></g><g font-family="Arial,sans-serif" fill="#081d37" font-size="27"><text x="65" y="630">01  Plan your budget.</text><text x="65" y="717">02  Compare the terms.</text><text x="65" y="804">03  Prepare your next step.</text></g><rect x="65" y="888" width="310" height="62" rx="31" fill="#081d37"/><text x="100" y="928" font-family="Arial,sans-serif" font-size="20" fill="#fff">Talk to Betterway</text><text x="65" y="1055" font-family="Arial,sans-serif" font-size="16" fill="#48685e">hello@betterwaymortgages.com</text><text x="65" y="1175" font-family="Arial,sans-serif" font-size="12" fill="#708782">Illustrative planning interface. Lender approval, fees and terms apply.</text>'''
(OUT/'betterway-banner.svg').write_text(svg(1600,900,banner))
(OUT/'betterway-flyer.svg').write_text(svg(900,1200,flyer))
print('Saved self-contained vector banner and flyer')
